from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1]
rows=[]
def add(key,authors,title,year,venue,url,version,locator,problem,objective,reward,algorithm,market,metric,result,studies,time,benchmark,relation):
 rows.append(dict(key=key,authors=authors,title=title,year=year,venue=venue,url=url,version=version,locator=locator,problem=problem,objective=objective,reward=reward,algorithm=algorithm,market=market,metric=metric,result=result,studies_reward_objective=studies,time_inconsistency=time,known_benchmark=benchmark,project_relation=relation))
add('kolm2019','Petter N. Kolm; Gordon Ritter','Dynamic Replication and Hedging: A Reinforcement Learning Approach',2019,'The Journal of Financial Data Science 1(1), 159–171','https://doi.org/10.3905/jfds.2019.1.1.159','16-page author manuscript at smallake.kr; figures are missing in this manuscript. Text and equations read; journal PDF unavailable.','“Automatic hedging in theory”, manuscript pp. 7–8, Eqs. (8)–(10), footnote 4; “Automatic hedging in practice”, pp. 9–14, Exhibits 1–5.','Discrete option hedging with nonlinear trading costs.','Terminal wealth mean–variance, then a simplified sum of increment variances.','Δw − (κ/2)(Δw)², explicitly approximate.','Batch fitted action-value learning with one-step SARSA targets and nonlinear regression.','Simulated GBM European call; strike/spot 100, 10 days, 5 decisions/day; κ=.1.','Hedging P&L, costs, volatility; comparison to delta hedging.','Reports lower cost across 10,000 test paths; volatility difference not significant at 99%.','Yes: explicitly discusses covariance and approximation.','Does not formulate a subgame equilibrium in the inspected derivation.','BSM hedge in frictionless limit; not a solved frictional optimum.','Closest raw-reward baseline. We isolate policy mismatch in a different allocation benchmark; do not infer failure of their hedger. Published κ/2=.05 is a units-sensitive diagnostic only.')
add('jiang2017','Zhengyao Jiang; Dixing Xu; Jinjun Liang','A Deep Reinforcement Learning Framework for the Financial Portfolio Management Problem',2017,'arXiv preprint 1706.10059','https://arxiv.org/abs/1706.10059','arXiv v2, 16 July 2017; saved PDF.','§§2.2–2.4, §4.2 Eqs. (21)–(22), §4.3; Tables 1–2; §6.','Long-only cryptocurrency allocation with costs.','Portfolio growth.','Average log portfolio growth including transaction-cost factor.','Direct gradient ascent; EIIE CNN/RNN/LSTM policies and portfolio-vector memory.','Poloniex, 11 noncash assets plus Bitcoin cash, 30-minute decisions; three 2016–2017 backtests.','Final accumulated value, Sharpe, maximum drawdown.','EIIE variants report leading accumulated values in all three tests (Table 2).','Yes: log reward corresponds to multiplicative growth.','No terminal mean–variance equilibrium objective.','Trading comparators, no known true market optimum.','Adapt log growth on an identical bounded action set. Different target preferences explain disagreement; their own growth objective is not mis-specified.')
add('yang2020','Hongyang Yang; Xiao-Yang Liu; Shan Zhong; Anwar Walid','Deep Reinforcement Learning for Automated Stock Trading: An Ensemble Strategy',2020,'Proceedings of the First ACM International Conference on AI in Finance (ICAIF), 8 pages','https://doi.org/10.1145/3383455.3422540','Columbia-hosted author manuscript; saved PDF. Do not use the later 2025 arXiv upload as a 2020 identifier.','§3.3 Eq. (4); §5 ensemble selection; §6.1 and Fig. 4; §6.2.4 and Table 2.','Automated constrained stock trading.','Portfolio value growth with costs and turbulence control.','Change in portfolio value net of transaction costs.','PPO, A2C, DDPG; rolling Sharpe-based ensemble selection.','Dow 30 daily WRDS data; training 2009–2015, testing Jan. 2016–8 May 2020.','Return, volatility, drawdown, Sharpe.','Table 2: ensemble Sharpe 1.30, DJIA .47, minimum variance .45.','Defines value-change objective; no identity with terminal MV.','No equilibrium mean–variance treatment.','DJIA and minimum-variance comparator, no true dynamic optimum.','Adapt value increments with zero costs and undiscounted finite horizon. Measures preference alignment; does not reproduce PPO/DDPG or the historical result.')
